import {cloudMode,hasSession,openSession} from './services/apiClient.js';
import {store} from './services/store.js';
const root=document.getElementById('app');let started=false;
function screen(message='',login=true){root.innerHTML=`<main class="cloud-entry"><div class="brand-mark">T<span>˙</span></div><span class="eyebrow">TALLERPRO V0.4 CLOUD</span><h1>Tu taller, conectado.</h1><p>Clientes, vehículos e historia compartidos entre dispositivos.</p>${login?'<form id="cloud-login"><label class="field">Código de acceso DEMO<input type="password" name="code" required autocomplete="current-password"></label><button class="btn primary full">Abrir TallerPro</button></form><p class="hint">Demostración compartida. Usa datos ficticios; las personas con el código pueden consultar y editar este taller.</p>':'<button class="btn primary" id="cloud-retry">Reintentar conexión</button>'}<p id="cloud-error" role="status"></p></main>`;document.getElementById('cloud-error').textContent=message;document.getElementById('cloud-login')?.addEventListener('submit',async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{await openSession(e.target.elements.code.value);await start();}catch(error){document.getElementById('cloud-error').textContent=error.message;button.disabled=false;}});document.getElementById('cloud-retry')?.addEventListener('click',start);}
async function start(){try{if(cloudMode()){root.innerHTML='<main class="cloud-entry"><h1>Conectando con tu taller…</h1><p>Cargando los datos compartidos.</p></main>';await store.refresh();}if(!started){await import('./app.js');started=true;}else location.reload();}catch(error){screen(error.message,!hasSession());}}
if(cloudMode()&&!hasSession())screen();else start();
window.addEventListener('tallerpro:session-expired',()=>{if(started)location.reload();});
